	// idempotency: read
	// deadline: 5 s
	// stream: none
	// errors: STATE/not_found
	// locality: cloud
	GetPhonePairing(context.Context, *v1.NodeEnrollmentServiceGetPhonePairingRequest) (*v1.NodeEnrollmentServiceGetPhonePairingResponse, error)
	// The desktop user's decision, relayed by the node.
	// auth: node credential (HUMAN decision on the node)
	// idempotency: command_id
	// deadline: 10 s
	// stream: none
	// errors: STATE/not_found, STATE/invalid_state, STATE/expired
	// locality: cloud
